'use strict';
const SpaceCatalog={
 data:null,sequence:0,esc:v=>UI._escHtml(String(v??'')),
 shell(){queueMicrotask(()=>this.load());return '<div class="card"><div class="card-title">可租赁空间管理</div><p class="form-hint">统一维护空间，供完整流程与简易流程选择。参考租金不替代项目商定金额，修改不会改变已有租赁价格。</p><div id="space-catalog-content">正在读取空间资料…</div></div>';},
 async load(){const seq=++this.sequence;try{const d=await Store._request('GET','/rest/v1/space-catalog');if(seq!==this.sequence||!document.getElementById('space-catalog-content'))return;this.data=d;this.render();}catch(e){const el=document.getElementById('space-catalog-content');if(el)el.textContent='空间资料读取失败：'+e.message;}},
 render(){const el=document.getElementById('space-catalog-content');if(!el||!this.data)return;const badge=document.querySelector('[data-ptab=spaces] .badge');if(badge)badge.textContent=this.data.spaces.length;const price=v=>v>0?'¥'+UI._fmt(v):'未设参考价';el.innerHTML=`<div class="filter-bar"><button class="btn btn-primary" onclick="SpaceCatalog.edit()">新增空间</button><span class="form-hint">${this.data.spaces.filter(r=>r.active).length} 个启用 · ${this.data.spaces.length} 个空间</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>空间名称</th><th>说明</th><th>半日参考租金</th><th>日参考租金</th><th>状态</th><th>历史登记</th><th>操作</th></tr></thead><tbody>${this.data.spaces.map(r=>`<tr><td>${this.esc(r.name)}</td><td style="white-space:pre-wrap">${this.esc(r.desc)}</td><td>${price(r.halfDayPrice)}</td><td>${price(r.dailyPrice)}</td><td>${r.active?'启用':'已停用'}</td><td>${r.usedCount} 条</td><td class="row-actions"><button class="btn btn-sm btn-secondary" data-id="${this.esc(r.id)}" onclick="SpaceCatalog.edit(this.dataset.id)">编辑</button><button class="btn btn-sm btn-secondary" data-id="${this.esc(r.id)}" onclick="SpaceCatalog.toggle(this.dataset.id,this)">${r.active?'停用':'启用'}</button>${r.usedCount?'':`<button class="btn btn-sm btn-danger" data-id="${this.esc(r.id)}" onclick="SpaceCatalog.remove(this.dataset.id,this)">删除</button>`}</td></tr>`).join('')||'<tr><td colspan="7">暂无空间，请新增。</td></tr>'}</tbody></table></div>`;},
 edit(id){if(!Auth.isAdmin)return UI.toast('仅管理员可维护空间','error');const r=id?this.data.spaces.find(r=>r.id===id):{id:crypto.randomUUID(),name:'',desc:'',halfDayPrice:0,dailyPrice:0,active:true,usedCount:0};if(!r)return;this.editing=r;const input=(key,label,value,type='text')=>SpaceProjects.input('sc-'+key,label,value,type);SpaceProjects.modal('space-catalog-edit',id?'编辑可租赁空间':'新增可租赁空间',`<div class="form-grid">${input('name','空间名称',r.name)}${input('half','半日参考租金（元）',r.halfDayPrice,'number')}${input('daily','日参考租金（元）',r.dailyPrice,'number')}<div class="form-group"><label for="sc-active">状态</label><select id="sc-active"><option value="true">启用</option><option value="false">停用</option></select></div><div class="form-group full"><label for="sc-desc">空间说明</label><textarea id="sc-desc" rows="3" maxlength="2000">${this.esc(r.desc)}</textarea></div></div><p class="form-hint">${r.usedCount?'该空间已有租赁记录，名称保留；需要更名请停用原空间并新增。':'参考租金可填0，表示暂未设定。'}停用后不接受新登记，已有项目和历史日历保留。</p><div class="modal-actions"><button class="btn btn-secondary" onclick="document.getElementById('space-catalog-edit').remove()">取消</button><button class="btn btn-primary" onclick="SpaceCatalog.save(this)">保存空间</button></div>`);document.getElementById('sc-active').value=String(r.active);document.getElementById('sc-name').readOnly=!!r.usedCount;},
 async persist(spaces){this.data=await Store._request('POST','/rest/v1/space-catalog',{version:this.data.version,spaces});await Store.loadAppConfig();this.render();},
 async save(btn){btn.disabled=true;try{const r={...this.editing,name:document.getElementById('sc-name').value.trim(),desc:document.getElementById('sc-desc').value,halfDayPrice:Number(document.getElementById('sc-half').value),dailyPrice:Number(document.getElementById('sc-daily').value),active:document.getElementById('sc-active').value==='true'};const found=this.data.spaces.some(x=>x.id===r.id);await this.persist(found?this.data.spaces.map(x=>x.id===r.id?r:x):[...this.data.spaces,r]);document.getElementById('space-catalog-edit').remove();UI.toast('空间资料已保存');}catch(e){UI.toast(e.message,'error');}finally{btn.disabled=false;}},
 async toggle(id,btn){const r=this.data.spaces.find(r=>r.id===id);if(!r||!confirm(r.active?'停用后不再接受该空间的新登记，已有项目和历史记录保留。确认停用？':'确认重新启用该空间？'))return;btn.disabled=true;try{await this.persist(this.data.spaces.map(x=>x.id===id?{...x,active:!x.active}:x));UI.toast(r.active?'空间已停用':'空间已启用');}catch(e){UI.toast(e.message,'error');}finally{btn.disabled=false;}},
 async remove(id,btn){const r=this.data.spaces.find(r=>r.id===id);if(!r||r.usedCount||!confirm('确认删除尚无租赁记录的空间「'+r.name+'」？'))return;btn.disabled=true;try{await this.persist(this.data.spaces.filter(x=>x.id!==id));UI.toast('空间已删除');}catch(e){UI.toast(e.message,'error');}finally{btn.disabled=false;}}
};
